System.register("chunks:///_virtual/%E5%89%A7%E6%83%85%E8%A1%A8.ts",["cc","./%E5%B7%A5%E5%85%B7%E5%87%BD%E6%95%B02.ts","./%E5%AD%98%E6%A1%A3%E6%95%B0%E6%8D%AE.ts"],(function(n){var t,u,r,c,i,o,f,e;return{setters:[function(n){t=n.cclegacy},function(n){u=n.开始剧情,r=n.进入战斗,c=n.计算最大生命,i=n.移动至,o=n.返回主界面,f=n.切换场景},function(n){e=n.保存存档}],execute:function(){t._RF.push({},"3f47bhVdRtNwaQGXb52/kry","%E5%89%A7%E6%83%85%E8%A1%A8",void 0);n("剧情表",{"过场":{"文本":["清晨的阳光落在山间的小屋；","拥抱过刚刚睡醒的晓月，","我背起木弓，开始了一天的狩猎。"]},"隐居总结":{"条件":function(){return 2===m.天数},"文本":["一个月前，我和晓月逃到这座大山。","南方温和的气候、险峻的山势给“隐居”提供了独特的环境。","晓月如同一个闯进魔法世界的孩子，常常兴奋不已。","然而，","越是如此，我越感到不安..."],"选项二":"继      续","结果二":function(n){var t=n.结束剧情;e(),t("【主角】系统开启！请在主界面查看。")}},"山涧拾栗":{"条件":function(){return 3===m.天数},"文本":["吃过早饭，我拎着布兜，带晓月去后山。","那儿有几棵野板栗树，秋天落了果，没人捡。","地上全是带刺的栗苞，我蹲着用石头一个个敲开，晓月站旁边，把果仁捡进篮子。","装了半兜，旁边树丛嗡的一声，一群野蜂飞了出来。","我抓起晓月的手腕就往山涧跑。","两个人踩着湿石头钻进一个浅山洞，等蜂群散了才敢出来。","回去一看，板栗撒了大半。","好在都没挨蜇，顺手又捡了些干柴，也不算白跑。"],"选项二":"继      续","结果二":function(n){var t=n.结束剧情;m.物品.松木+=5,m.物品.食物+=3,t("获得「松木」*5，「食物」*3")}},"晓月唤我":{"条件":function(){return 4===m.天数},"文本":["“阿飞（晓月对我的昵称...）！救命呀~救命呀！”晓月慌慌张张跑进来。","我抬眼看她。","“屋檐上有一只肉呼呼、红扑扑的大虫！一根毛都没有呐！~”她一边说一边比划。","我把剥开的野板栗递过去，她嚼着问：“今天吃啥？”","“清蒸鼻涕虫~”","..."]},"私奔往事":{"条件":function(){return 5===m.天数},"文本":["两年前，我从老家一路流浪到这座南方省城，靠一点手艺混口饭吃。","摆摊卖手艺品的时候认识了晓月——她就在不远的地方给人画肖像。","晓月温柔、活泼，人也善良。她爸是省城钢铁厂的领导，她妈早年病走了。","我是在山沟里长大的，妈小时候就离开了，跟我爸一直不对付，心事重。","她爸死活不同意我俩。我脾气倔，又冲，跟他吵过好几回。","最后我带着晓月跑了，跑到这儿——半山腰上一间没人要的护林屋。"],"选项二":"继      续","结果二":function(n){var t=n.结束剧情;m.伙伴.晓月.关系=!0,e(),t("【晓月】系统开启！请在主界面查看。")}},"屋漏修缮":{"条件":function(){return 6===m.天数},"文本":["后半夜下了场雨。","天亮一看，屋顶一块木板松了，水顺着缝往下滴，正好滴在床边。","我搬梯子上房，晓月在下面扶着梯子，给我递木片和钉子。","忙到中午，总算补好了。","回屋的时候，晓月煮好了红薯粥，坐在桌边等我。"]},"无情之人":{"条件":function(){return 7===m.天数},"文本":["我一直觉得自己没什么感情。","我爸随手砸过来的酒瓶，同学求饶时的眼泪，都没让我心里动过一下。印象里我没哭过。","可到了晓月面前，我有时候幼稚得像个小孩子。","为什么，我说不清。"]},"林间嬉闹":{"条件":function(){return 8===m.天数},"文本":["“这个地方，应该这么削，懂吗？”","“不懂。”","“当心我捏你哦~”","“来呀！”晓月笑着跑开。","我没追。","没一会儿她又跑回来，拉着我的手看我。我把眼睛挪开了。","“走吧，咱们去爬山吧~”","就这么被她牵走了。"],"选项二":"下篇继续"},"山顶之问":{"条件":function(){return 9===m.天数},"文本":["我们先穿过一片没什么声音的松林往上爬。倒下的松树上开着紫色的小花，脚下的青苔软，踩上去窸窸窣窣。","到了山顶，找了块地方坐下。","山下的路细得像根带子。我盯着那条路，把憋了很久的话问了出来——","“你想家吗？”","在问这个问题时，我故意看着远方，示意她不用急着回答。"],"选项二":"继      续","结果二":function(){u("晓月心声")}},"晓月心声":{"文本":["她愣了很久，抓住我的胳膊，把脸靠在我肩上：“我觉得，现在很好，我不需要更多了。”","我长出一口气。这正是我怕听到的答案。","在快乐的表象下，掩埋着一颗厌倦的种子，它迟早会发芽、开花、结果，而我却无力阻止。","我能做的，现在唯一能做的，就是快些攥够钱，实现那个计划。"]},"相约进城":{"条件":function(){return 10===m.天数},"文本":["初秋。清早的山谷里飘着薄雾。","我打算进一趟县城，把攒了多日的货卖掉。","“要不我也去？”晓月说，“我能帮你拎点。”","我犹豫了一下。跑出来以后，她爸一直在找她。计划没办成之前，我们不想被找到，也不想分开。","“我可以戴帽子！”她眼睛亮着看我。","“行吧。”其实我也想让她跟着。"],"选项二":"继      续","结果二":function(){return u("摊位争执")}},"摊位争执":{"文本":["到了县城古玩街，我那个摊位上铺了块红布，上面摆着首饰，一个小伙蹲在旁边抽烟。","我把货往地上一放，走过去：“兄弟，不好意思，这位置是我的。”摆摊这行有规矩，一个位置归一个人，互不相抢。","他把我从头到脚看了一遍，站起来，抱着胳膊，故意把纹身露出来：“这上边写你名字了？你能摆，我就不能？”","晓月也跟了上来，赶紧把我往边上拉——","【你要怎么做？】"],"选项一":"算了，让给他，再去找别的位置","结果一":function(n){var t=n.结束剧情;m.剧情.高级摊位占用=!0,t("高级摆摊点已被纹身男占领")},"选项二":"不行，不能让，争执到底！","结果二":function(){return r("纹身男")}},"秋夜观星":{"条件":function(){return 11===m.天数},"文本":["夜里，晓月拉着我往外跑。","“快点快点！”","抬头一看，天很干净，星星密密麻麻铺满了。","她躺在草坡上，一颗一颗数星星。","“小时候，我妈说，人死以后会变成天上的星星。”","“骗人的。”","“我知道呀。”她笑着看我，“可小时候就是信嘛。”","过了一会儿，她又小声说：“要是以后真有那么一天，你记得看看天。”","我没接话，也躺下去，陪她看天。"]},"买麦芽糖":{"条件":function(){return 12===m.天数},"文本":["傍晚收摊，卖剩的货装进袋子，往回走。","晓月走在前头，帽子摘下来背在身后，时不时回头跟我说她的新发现。夕阳把她的影子拉得很长。","迎面来了个卖糖的。","“要不要来点？”我跟上去，盯着她眼睛问。","晓月眼睛一下睁大，又赶紧垂下去：“哎呀，算了吧~小孩子吃的东西~”","“偶尔吃一次也没什么~”我拉着她的手，把小贩喊住了。","【给晓月买吃的吗？】"],"选项一":"不买了","结果一":function(n){return(0,n.结束剧情)("小贩停住担子愣在原地，疑惑地打量着你们二人。")},"选项二":"全部的钱！（最多花10元）","结果二":function(n){var t=n.修改选项二,u=n.结束剧情;if(m.金钱>0){var r=Math.min(m.金钱,10),c=10*Math.floor(r),i=Math.ceil(.2*c);m.金钱-=r,m.伙伴.晓月.精力+=c,m.当日加成.祝福+=i,u("你花费"+r+"元给晓月买了麦芽糖，晓月精力提高"+c+"，祝福提高"+i+"！")}else t("你根本没有钱！")}},"途遇老猎":{"条件":function(){return 13===m.天数},"文本":["那天我一个人进山查陷阱，穿过一片松林，碰上一个背着猎枪的老头。","他看了看我下夹子的地方，蹲下来拨了拨地上的痕迹。","“兔子不会走这里。”他说，“山里的东西，都有自己的路。”","他指着旁边几条不显眼的小路，告诉我哪儿容易留脚印。","临走从褡裢里掏出一个自己打的铁夹子，塞给我。","“年轻人进山不容易，拿着吧。”","我想推，看了一眼他那双手，还是收下了。"],"选项二":"继      续","结果二":function(n){var t=n.结束剧情;m.物品.兽夹+=1,t("你收下了捕兽夹，也记住了这份陌生的善意。")}},"欲望思考":{"条件":function(){return 14===m.天数},"文本":["事实上，对于钱，我本无多大兴趣。","对我而言，这个世界上既没有难吃的食物，也没有好吃的食物——我似乎从小就缺乏欣赏生活的能力。","然而现在，我不再是一个人，伴随而来的是——欲望也开始变多。","这算正常的转变，还是坏的开头，我不知道。"]},"山溪抓鱼":{"条件":function(){return 15===m.天数},"文本":["上午带晓月去山溪。水浅，小鱼在石缝里钻来钻去。","她卷起裤腿蹲进水里，两只手慢慢凑过去，眼看要抓到，鱼尾巴一摆，跑了。","“哎呀！”","她不服，又扑了一下，脚下一滑，一屁股坐进水里。","我站在岸上，看她湿成那样，没忍住笑出声。","“你居然笑我！”她捧起水朝我泼过来。","回家的时候，两个人都湿透了。"]},"弱者伙伴":{"条件":function(){return 16===m.天数},"文本":["摆摊那几个月，有两个人我一直记着。","一个是中年城管。他不硬赶人，每次都慢慢劝。被劝走的小贩——包括我——等他走了就回来接着摆。他同事好像不太待见他，从不跟他一块执勤。","另一个是卖旧书的胖小伙，戴眼镜，别人叫他小胖。只卖古典名著和百家经典，从不吆喝，埋头看书。我原先以为他是来体验生活的，后来看见他翻垃圾箱，就不这么想了。","有时候我想，我会注意到这两个人，大概是因为我们身上有同一种东西。","——弱者。"]},"城管闲谈":{"条件":function(){return 17===m.天数},"文本":["半个月前的一个下午，那中年城管走到我摊前，没赶我，掏出烟蹲在旁边抽，转头问：“总一个人坐着发呆，不闷吗？”","“习惯了。”我没看他。不是瞧不起，是我不知道跟不熟的人说话，眼睛该往哪儿放。","“多跟周围摊友聊聊，一个人会憋坏的。我一天不说话就难受得要命。”","“卖的又不是同一个东西，没啥可聊的。”","“你还年轻，有些事不明白。出门在外靠朋友，太孤僻的话……”","“不用你管！怎么做是我自己的事。”我突然就火了。","他没再说话，一直抽烟，手有点抖。抽完就走了。"],"选项二":"继      续","结果二":function(){return u("事后懊悔")}},"事后懊悔":{"文本":["他走了以后，我有点后悔。","我知道他没恶意。可我为什么这样，我也不知道。","我试着想过自己为什么生气，没想出来。好像心里有样东西，专门往外推别人的好意。但我觉得，还有更深的原因。"]},"摆摊被抓":{"条件":function(){return 18===m.天数},"文本":["上午照旧去古玩街摆摊。","屁股还没坐热，街口哨子一响，十几个摊贩抱着货四散跑。","我刚要收，一个城管领导已经站到摊前。","“谁让你在这儿摆的？”他脸沉着。","我没有回答。"],"选项二":"继      续","结果二":function(){return u("城管救场")}},"城管救场":{"文本":["那个中年城管快步赶过来。","“是我的责任。”他说，“那边有人闹事，我过去处理，没顾上这边。”","领导瞪了他一眼：“回去写检查！”","领导走了，他弯下腰，帮我把地上的木雕一个个摆回去。","“以后跑快点。”他笑了笑，接着巡街去了。","我看着他的背影，直到人堆把他吞掉。"]},"偶遇城管":{"条件":function(){return 19===m.天数},"文本":["一天早上我去县城买米，前头一个背影眼熟，正是那个中年城管。我脚步一下慢了。他好像觉出后头有人，回头看了一眼，冲我挥手，大声喊：“上街呐——”","“嗯。”我只好走过去。这一句说完就没什么话了，两个人并排走着。","“你认不认识那个卖玉器的小伙？”他忽然问。","“不认识。”我知道他说的是纹身那个，又多问了一句，“怎么了？”"],"选项二":"继      续","结果二":function(){return u("城管诉苦")}},"城管诉苦":{"文本":["“前些天这小伙提着东西上我家，让我照顾照顾他生意。我没答应，还说了他两句。第二天他就在我儿子上学的路上把人拦住，打了两个耳光，还撂话说‘这只是一个开始’。我儿子现在不敢去学校了。”","我沉默了一会儿：“那你打算怎么办？”","“找他父母去，跟大人说说。这小伙不懂事，稀里糊涂的，有人扶一把还能掰回来。”","我不知道该说什么。他倒像是说开了，脸上有了笑：“对了，三天后有领导来县里视察，不让摆摊，最好别出来。”我又嗯了一声。","快到县城，我们就分开了。我没想到，这一分开就是永别。"]},"城管受屈":{"条件":function(){return 20===m.天数},"文本":["这天摆摊，街对面忽然围了一圈人。我抬头，看见那中年城管正在扶一个摔倒的老太太。","没一会儿，一个中年男人跑过来，一把把他推开：“是不是你撞的？”","他赶紧解释，说只是上去扶了一把。男人不信，越说越激动，围观的人也跟着议论。","老太太慢慢坐起来，看了看城管，又看看自己儿子，小声说：“不是他……”","男人脸色很难看，一句道歉都没有，扶着老太太走了。人也散了。","他拍了拍裤腿上的灰，苦笑了一下，接着往前走，好像刚才那事没发生过。"]},"城管遇害":{"条件":function(){return 21===m.天数},"前置执行":function(){m.生命=Math.floor(.1*c()),m.状态.恐惧=!0,i("县城"),m.剧情.纹身男状态="逃走"},"文本":["那天上午，我买完米从商店出来，往家走。远处一堆人围着什么。","我走过去。人堆中间躺着一个人，一个男人，躺在血里。胸口插着刀，两只手还握着刀柄，眼睛睁着。是那个中年城管。","我嘴唇开始抖，喘不上气。米袋掉在地上。","这是我头一回真正撞见死。我幻想过无数次自己浴血奋战，真到了跟前，剩下的只有怕，还有难受。","周围人议论纷纷，警察在维持秩序。几个目击者说，是那个卖玉器、手臂上纹身的小伙干的，为什么不知道。没多久救护车来了，把人抬走，人也慢慢散了……"]},"废品老本行":{"条件":function(){return 22===m.天数},"文本":["他出事以后，政府给家里送了抚恤金，县里也开始禁摊。纹身那个小伙找不着了，城里到处贴着他的悬赏通告。","我还是会去县城，但没以前那么勤。","摆摊没了收入，我一个人进城的时候就带个塑料袋，沿路捡瓶子，拿去废品站卖。这事我瞒着晓月。"]},"忘带午饭":{"条件":function(){return 23===m.天数},"文本":["在山里把陷阱布完，才想起来没带午饭。正要回去，远远看见晓月提着竹篮爬上坡，气都喘不匀。","“就知道你又忘了。”她把饭盒塞我手里，坐在石头上擦汗。","饭有点凉了。我低头吃。","她笑着逗我：“以后老了，你肯定天天忘事。”","“不会。”","“会。”","她答得很肯定。"]},"愤怒魔鬼":{"条件":function(){return 24===m.天数},"文本":["山里的夜一般很吵：虫叫、溪水响、树叶哗啦，偶尔还有野兽叫。这天晚上却静得出奇。","火苗在晓月眼睛里晃。我把下巴搭在桌上，小声说：“我总觉得心里住着个魔鬼。明明不想发火，就是控制不住。”","她眯起眼睛笑：“每个人都有吧~”","“这‘魔鬼’到底是什么？”我皱着眉。","她眼珠转了转：“可能是……习惯？我也不知道。”","..."]},"初遇小胖":{"条件":function(){return 25===m.天数},"文本":["九月末的一天，我从废品站出来，看见一个胖小伙蹲在地上捡书——是卖旧书的小胖。他装书的编织袋穿了底，书撒了一地。","要是以前，我直接走过去，装没看见。这回我停住了，可又不好意思上去帮。就把手里的塑料袋拎得高高的，等他收拾完。","他把书摞好，才发现旧袋子不能用了，垂头丧气坐在地上。过了一会儿他看见我手里的袋子：“嘿！兄弟~”他指了指地上的书，“袋子借我用用行吗？我家就在附近，马上还你。”","我把袋子递了过去。"],"选项二":"继      续","结果二":function(){return u("三中开放")}},"三中开放":{"文本":["有一摞书实在塞不进袋子，我抱着，跟他回了住处。","一层红砖房，墙角堆着废纸和塑料瓶，床上的被子油得发亮。我放下书，把袋子收回来，刚转身，他喊住我：","“等一下！我……我找了个摆摊的好地方。看你以前也卖东西，要不要去看看？”","“哪儿？”","“县三中。”","三中在县城郊外，偏，周围连个商店都没有，学校连围墙也没有，是县里出了名的乱。里头的孩子，多半是被附近山民随手“丢”进来的。","我答应了。"],"选项二":"继      续","结果二":function(n){var t=n.结束剧情;m.精力+=20,t("触发【价值体验】，获得精力20点")}},"木屋午睡":{"条件":function(){return 26===m.天数},"文本":["中午没事干，晓月搬了把竹椅坐到外面，把头靠在我肩上晒太阳。","山风一阵一阵的，林子里偶尔叫两声鸟。","没一会儿她就睡着了。我不敢动，就那么坐着。","太阳快落山她才醒，揉着眼睛。","“你怎么不叫我？”","“没事。”","她伸了个懒腰，笑：“以后老了，也这样晒太阳吧。”"]},"三中摆摊":{"条件":function(){return 27===m.天数},"文本":["第二天一早，我跟小胖去三中。","初中，建在半山腰。中间一栋三层白楼，周围散着几间大大小小的瓦房。","几个学生蹲在一间破瓦房边上打稀饭。那是寝室，给几个家太远的学生住，管口饭。","屋檐下蹲着个男生，看我们走过去，抬了下眼皮，又低头喝粥。对生面孔一点兴趣都没有。","我们在一棵大树下支好摊。小胖像被拧开的水龙头，跟我讲起他的过去。"],"选项二":"下篇继续","结果二":function(){m.伙伴.小胖.关系=!0,o(),i("三中")}},"小胖身世":{"条件":function(){return 28===m.天数},"文本":["小胖，25岁。","四年前从专科的中医学毕业，先进了一家药企。","“其实就是做销售。”他解释，“天天打电话，打几百个也谈不成一单。”“干了半年，被辞退了。”","“怎么不去医院当医生？”我问。","“进不去呀！”他这话里有气，也有没办法，“这么说吧，我那些同学，最后干什么的都有——帮人卖东西的、替人开车的、给人按摩的——就是没有当医生的。”"],"选项二":"继      续","结果二":function(){return u("小胖身世2")}},"小胖身世2":{"文本":["药企出来以后，他进了电子厂。","“一天八小时重复一个动作，还得倒夜班！”“大热天，10平米的房间挤12个人！”“干了一年就不干了~”","辞了以后晃了一个月，最后去了一家烧烤店。","“这段其实还挺怀念的。每天收工都有宵夜，我就是那时候胖起来的。”“可惜一年半就倒了。”“那会儿快春节了，我就回了老家。”","“在家待了三个月。我爸没说什么，我妈最后一个月几乎天天念我，我又跑出来了。”"],"选项二":"继      续","结果二":function(){return u("卖书启发")}},"卖书启发":{"文本":["“那时候挺茫然的，不知道干啥。后来钱花光了，想到县城房租便宜，就过来了，中间还捡过几次瓶子。”","“后来怎么卖上旧书的？”这是我第二次打断他。","“也算是巧合。到了县城，我开始看百家经典，尤其《道德经》，挺受用，人也没那么拧了。本来我只是去废品站给自己找书，后来一想，这么好的东西，为什么不推出去？一本好书真能改变人的一辈子，尤其是那些在念书、又买不起书的孩子。我就做起卖旧书的生意了。大事我做不了，那就从最小的地方开始。”","我没说话，也不知道该接什么。我只清楚一点：他怎么活，是他自己的事。"],"选项二":"继      续","结果二":function(){return i("三中")}},"三中樟树":{"条件":function(){return 29===m.天数},"文本":["三中边上有一棵巨大的樟树。","树底下，面朝学校那边是一个水泥糊的乒乓球台和生锈的单杠，学生在这儿玩。背对学校那边，地上全是烟头和酒瓶，树皮上到处是打火机烧过的印子，还有小刀刻的“爱慕”。一边是玩的，一边是混的。","树上一根枝子烂了，长满青苔和树菇。秋天的光从叶子缝里漏下来，落在青苔上晃。","我和小胖的摊就摆在这棵樟树下。这里不光有学生，过路的老乡也爱在这儿歇脚。生意比县城差远了，但总归有点进项。"]},"三中旧书":{"条件":function(){return 30===m.天数},"文本":["下午没什么人。一个瘦小的男生在摊前站了很久，拿起《钢铁是怎样炼成的》翻了翻，又放回去。","“多少钱？”他低着头问。","“五块。”小胖笑。","男生从口袋里摸出两枚硬币，又收了回去。","“算了。”"],"选项二":"继      续","结果二":function(){return u("小胖赠书")}},"小胖赠书":{"文本":["“拿去吧。”小胖把书递过去。","男生愣住：“我……没钱。”","“以后有了再给。”","男生抱着书连说了几声谢谢，转身跑回学校。","我看着那背影：“他要是不回来呢？”","小胖把书摆回原位：“总有人会回来。就算他不回来，那本书也会留下点什么。”","我没再说话。"]},"木雕礼物":{"条件":function(){return 31===m.天数},"文本":["下午我在削一块边角料，晓月趴在桌边看。没多久，一只巴掌大的木兔刻好了。","“送给你的。”","晓月接过木兔翻来覆去地看，忽然很认真地问：“以后别人给钱，你也给他们刻吗？”","“会。”","她嘟起嘴：“那我这只就不特别了。”","我想了一下，拿起刻刀，在兔子底下刻了个小小的“月”字。","她这才笑了。"]},"树下争吵":{"条件":function(){return 32===m.天数},"文本":["一天中午，樟树后头传来吵架声。","“城里来的就了不起啊？看你这打扮，跟个婊子似的，知道吗！”声音尖，还带着股孩子气的凶。","“我从小就这样穿……”声音很轻，带着哭腔。","“这里不准这么穿，听见没！还有，给同学发零食是几个意思？收买人心？”","“我妈妈让我这么做的~”","“你妈让你不穿衣服，是不是你就不穿？你妈咋不叫你回去玩泥巴？”","“噗——！”小胖没忍住笑出来，还拍了两下大腿。"],"选项二":"继      续","结果二":function(){u("口角冲突")}},"口角冲突":{"文本":["几个女生围了过来。","前头几个穿布衣、汗衫，最后头那个穿一条好看的裙子——就是被围着骂的那个。","“谁笑的！”一个又黑又瘦的女生吼。","“我！”小胖举起一只手。","“笑啥？”\n“看书看到好笑的地方。”\n“再笑一个？”\n“笑过了，笑不出来。”","黑瘦女孩一脚把小胖摊前的书踢得满地乱飞。我一下从摊子后头窜起来，一脚把她踹倒。"],"选项二":"战  斗！","结果二":function(){i("三中"),r("黑瘦女孩")}},"晓月画人":{"条件":function(){return 33===m.天数},"文本":["雨停的下午，晓月翻出好久没用的画笔。","“你想画什么？”我问。","“画一个人。”","“谁？”","她低头想了一会儿：“以前的自己。”","我看纸上的女孩。","短发，裙子，站在城市的街上，笑着。"]},"雨中避居":{"条件":function(){return 34===m.天数},"文本":["赶走黑瘦女孩那天下午，天忽然下雨。","我们把货藏在离学校不远的一个土庙里，往家跑。半路碰上给我送雨衣的晓月，三个人一起跑到木屋。","屋里生了炭火烤衣服，说白天的事，说以后的打算，甚至说到将来一块儿租个门面。雨停了，小胖就回去了。","有一样的目标，一起做点事，大概就是朋友。可我总觉得，这段交情里少了点什么。"],"前置执行":function(){m.伙伴.晓月.健康=50}},"求购药方":{"条件":function(){return 35===m.天数},"文本":["那场雨之后，晓月小腿上起了疹子，抹了药膏也不见好。我心里不踏实，去找小胖。","到他家的时候，他正坐在门口看书。“你怎么来啦？！”他有点意外。","“啊，是这样……”我在他旁边坐下，有点说不出口，“最近我大腿上起疹子，一到晚上就痒，睡不踏实。你有没有什么法子？”","“哪儿？我看看。”小胖笑。","“不用不用，不严重，就几个红点。”我跟他把“自己的”症状说了一遍，说能止住痒就行。","“止痒是吧，我查查……”小胖认真起来，把我领进屋，从床底下翻出一本落满灰的书，一边翻一边念叨，翻了很久，抽出一支圆珠笔，把方子抄在一张纸片上：“你先按这个试试，不行再说……”"],"选项二":"继      续","结果二":function(){return u("寻人启事")}},"寻人启事":{"文本":["我拿着方子要走。","“等一下！我……给你看个东西。”他喊住我，眼神有点飘。我心里咯噔一下。","他从屋里拿出一张折了很多次的报纸，角落里一小块地方写着——\n“寻人启事：晓月，女，20岁，身高163cm，短发；2003年4月10日离家后至今未归，如有发现者请联系晓先生：158...，或拨打110报警电话；凡提供有用信息者，将给予2000元奖励。”旁边还贴着晓月的照片。","我倒吸一口凉气，脸绷住不动。","“这是我无意间看到的。照片上这女孩，很像你女朋友……”小胖连气都不敢出了。","“不是她。不过还真挺像。”我笑了一下。","“那就好~”他也笑了，像松了口气。"],"选项二":"继      续","结果二":function(){return u("归途心慌")}},"归途心慌":{"文本":["回去的路上，我腿有点软，干脆坐在路边，把刚才那一幕过了一遍。","冷静下来我知道，小胖当面问，是好奇，也是关心。可那会儿根本没时间想，我第一反应就是瞒。","为什么这么选，我自己都不清楚。也许那个多疑又胆小的我，才是真的我。"],"选项二":"继      续","结果二":function(){return"晓月生病后，精力恢复会大幅降低；你可以在「晓月」->「使用」中使用「搽拭」治疗晓月。"}},"夜听山雨":{"条件":function(){return 36===m.天数},"文本":["半夜下大雨。","雨点砸在屋顶上，山风把木门吹得咣当响。","晓月忽然醒了，小声问：“你睡了吗？”","“没有。”","“听这雨声，忽然想起咱们头一回一块儿过夜那晚。”","“那会儿你说怕打雷，二话不说就钻我这边来了。”","“其实我心里清楚，那晚你一夜没合眼。”"]},"敷药闲谈":{"条件":function(){return 37===m.天数},"文本":["回家照着方子把药捣好，先在自己脚上抹了点，没什么反应，才去叫晓月。","“怎么样？好点没？”我把她的裤脚放下来，顺手捏了下她的脚。","“嗯~凉凉的。”她捂着嘴笑。","“山里就这样，潮，温差大。真不行咱们去镇上租间房。”","“咦？话说你在山里住这么久，咋啥事没有？”她这话把话题拐跑了。","“我上辈子是只小强，丢哪儿都能活……”","..."]},"乡村收书":{"条件":function(){return 38===m.天数},"文本":["这天没出摊，小胖叫我一块儿下乡收旧书。连着走了四五个村子，大多人家都说没书。","快中午的时候，一个老人抱出一摞发黄的课本。“都是我孙子的。”老人说，“出去打工了，用不上了。”","小胖随手翻开一本语文书，里头夹着十几张奖状。","回程他一路没说话。快到县城，他忽然开口：“有时候我觉得，人扔掉的，不只是书。”"]},"相约出摊":{"条件":function(){return 39===m.天数},"文本":["十月末，天很蓝，太阳很好。晓月病了以后我就没去过三中。这天小胖拎着编织袋突然来了。","“怎么样？药方有没有效果？”","“啊……好多了。”","“哈哈，我还是有点用呀。”他挺高兴，好像上次那回事根本没往心里去，“听说三中在开运动会，人很多，要不要一块儿出摊？”","“好……好呀。”我进屋背上货，跟晓月说了一声。走的时候她还追出来，站在门口冲我们挥手。"],"选项二":"继      续","结果二":function(){return u("好友生疑")}},"好友生疑":{"文本":["一路上小胖不说话，像憋着事。我等他开口。","“我刚才……仔细估了一下你女朋友两眼之间的距离，眼睛到嘴的距离……这些特征不会随年龄变的……你知道我在说什么……”","我停下脚。“对不起。”心口跳得厉害，“我骗了你。”","“你在怕什么？怕我举报，还是怕我威胁你？！”他的脸扭得很难看，我从没见过他那样。","我没遇上过这种事。或者说，我从来没有过朋友，一时不知道该怎么办。解释？我确实是怕他举报。道歉？已经道过了。沉默？不行，越沉默越说不清。","我低着头没说话，意思是他给我点时间。他脸上的红退了一点，扭过头，加快脚步往三中走。我跟上去。"],"选项二":"下篇继续"},"制服后的决裂":{"条件":function(){return 40===m.天数&&m.剧情.制服花城四少},"文本":["把黑瘦女孩赶走以后，我没多高兴。我知道她们不会就这么算了，跟小胖匆匆离开三中。","不知道怎么回事，我没回木屋，跟着小胖去了他住处。我希望他说点什么，哪怕给我个台阶。","“我想知道，你到底是怎么想的。”他终于开口。","“说实话。”我让自己稳住，“我自己也不知道为什么要这么做。”","小胖冷笑了一声：“那就没什么好说的了。你很聪明，我以前挺服你的。可越处越觉得，你世界里只有你自己。你干什么都先算自己的感受，一笔一笔地算，斤斤计较。可能我和你就是两个世界的人。”","我愣在那儿。然后低头给他鞠了一躬——不知道合不合适，当时就是想鞠——转身走了出去。"]},"制服后的人际反思":{"条件":function(){return 41===m.天数&&m.剧情.制服花城四少},"文本":["有时候我会想，我和小胖是怎么一步一步走到今天的。","跟人打交道，我好像总开不了口。像在怕什么，又不知道怕什么。我想有人对我好，可嘴一张就是冷话，手一动就是狠事。","难道我的体内真的躲着一只魔鬼，在不经意间操控着我？","——不知道，真的不知道。"]},"恶女寻仇":{"条件":function(){return 40===m.天数&&!m.剧情.制服花城四少},"文本":["那天出摊有多别扭，可想而知。","学校来了不少看比赛的村民。几个老太太挎着篮子，见人就问：“要水吗？甘蔗呢？刚削的！”","我坐在摊前，一边想事一边看小胖，肩膀被人轻轻拍了一下。回头一看，是那天那个黑瘦女孩。她身边跟着四个“奇形怪状”的小伙，看打扮不像学生。","“诶，还记得我吗？”她有点得意。","“记得。”"],"选项二":"继      续","结果二":function(){return u("厕所对峙")}},"厕所对峙":{"文本":["“咱们去厕所聊聊。”她朝那四个人点了下头。","“不用麻烦，我自己会走。”我说得很大声，然后开始收地上的货。小胖也跟着把书收进编织袋。","我们跟着她走到学校最偏的一处厕所。里头一群男生在抽烟，见我们进来就散了，躲在门口偷偷看。","刚进门，我还没来得及开口，她一脚踢在我胯下：“你TM今天就准备死这儿吧！”"],"选项二":"战  斗！","结果二":function(){i("三中"),r("黑瘦女孩与花城四少")}},"受辱挨打":{"条件":function(){return 41===m.天数&&!m.剧情.制服花城四少},"文本":["那天我和小胖被四个人按在厕所墙上，头对头撞了七八下，撞得眼前发黑。","“你们谁从我胯下钻三圈，我就饶了谁。”她说。","我沉默了一会儿，从她胯下钻了过去。她哈哈大笑，还拍了我屁股两下。","小胖死活不肯。一个摘了他的眼镜，按着他的头，另一个拿膝盖顶他的脸。","我不知道顶了多少下。最后他躺在地上，瞪着眼，喘着气，满脸是血。"],"选项二":"继      续","结果二":function(){return u("荣辱之思")}},"荣辱之思":{"文本":["在老家，有些人宁可饿肚子，也不肯在面子的事上少花一分钱。我以前挺看不上这种人的。","面子上的屈辱，对我来说不算什么，转头就忘。只要做做样子就能躲开一顿打，我乐意。","可小胖不一样。当众受辱这事，他能记很久，难受很久，自卑很久。身上那点疼，几天就过去了。","同一件事，落到两个人身上，就成了两件事，选择也不一样。到底是什么在左右我们，我到今天也没想明白。要说全是因为过去的经历不同，我觉得不够。"],"选项二":"继      续","结果二":function(){return u("人际反思")}},"人际反思":{"文本":["跟受辱那件事比，我想得更多的是：我和小胖是怎么走到今天的。","跟人打交道，我好像总开不了口。像在怕什么，又不知道怕什么。我想有人对我好，可嘴一张就是冷话，手一动就是狠事。","是不是身体里真躲着个魔鬼，一不留神就替我做主？","——不知道，真的不知道。"]},"民警上门":{"条件":function(){return 43===m.天数},"文本":["受辱那事过了大概四天，我和晓月回木屋。门口蹲着两个男人，见我们回来就站起来，走过来掏出证件——","“别紧张，查下身份，有身份证吗？”","“没有。搁在老家了。”","“那就请跟我们走一趟吧。”"],"选项二":"继      续","结果二":function(){return u("分离讯问")}},"分离讯问":{"文本":["被带到警局以后，我和晓月就分开了。我被带进一个单独的房间。","“名字”，民警问。\n“陈飞”","“年龄。”\n“19”","“工作。”\n“木工、打猎。”","“为什么住山上？”\n“方便工作。”","“你跟那个女孩的关系是？”\n“男女朋友。”","......"],"前置执行":function(){m.精力=10,m.伙伴.晓月.关系=!1}},"警局相离":{"条件":function(){return 44===m.天数},"文本":["我在警局旁边坐了一晚上。第二天急着找到带我们来的那个民警，说明来意。他冷冷地说：“哦，那姑娘已经被送回家了。”","“哪个家？我怎么没见她出来。”","“老家啊。”","“为什么要送回老家？”","“是她自己要求的。有什么问题，你自己去问她。”他一脸不耐烦。","..."],"选项二":"继      续","结果二":function(){return u("奔赴省城")}},"奔赴省城":{"文本":["拖着疲惫的身子，我回到木屋；本想稍微休息一下，却怎么也睡不着。","为什么她要主动提出回家？是放弃了那个计划，还是发生了什么？","我越想越不对，干脆起身，简单地收拾了一下行李，匆匆赶往县城，踏上了去往省城的大巴。"],"选项二":"继      续","结果二":function(){return u("过场2")}},"过场2":{"文本":["车外的树影在车窗上快速划过，","车里嘈杂的人声突然变得很小、很小","——这是我在极度的疲惫与不安时才会出现的反应，","上次出现是在四年前，我十五岁的时候。","车停了下来。时隔一年，我再次踏上这片熟悉的土地。","不同以往，看着行色匆匆的人群，我内心充满着迷茫与恐惧；","我知道，平静的生活已经被撕开；或许，再也回不去..."]},"睡觉确认":{"文本":["系统检测到你还有多余的精力，确定要睡觉吗？"],"选项一":"返      回","选项二":"继      续","结果一":function(){o()},"结果二":function(){f("结算")}},"山中长眠":{"文本":["炭火灭了，山风顺着木缝钻进来。","浑身的疼早就麻了。我躺在木板上，连抬手的力气都没有。","晓月的哭声在耳边越来越远。我想说句话，喉咙里一点声音都出不来。","这间小屋装着我们所有的好日子。它成了我的终点。","【结局：山中长眠】"]},"山谷孤亡":{"文本":["山道上青苔太滑，我一头栽进乱石堆里。","林子里的鸟兽在叫。四下没人。风卷着落叶，一片片盖到我身上。","【结局：山谷孤亡】"]},"荒巷殒命":{"文本":["我拼着最后一点力气躲开街上的人，踉跄着钻进县城外一处废巷子。","四周是建筑垃圾和荒草。街上再吵，也听不见了。","伤口一直在渗血，眼前一点点发黑。","【结局：荒巷殒命】"]},"三中厕所":{"文本":["废厕所的臭味裹着我，地上的脏水把衣服都浸透了。","意识一点点往下沉。","【结局：三中厕所】"]}});t._RF.pop()}}}));

