System.register("chunks:///_virtual/%E6%97%A5%E8%AE%B0%E8%A1%A8.ts",["cc"],(function(t){var u;return{setters:[function(n){u=n.cclegacy}],execute:function(){u._RF.push({},"5949cREENBEwJKLxka9fLab","%E6%97%A5%E8%AE%B0%E8%A1%A8",void 0);t("日记表",[{"区域":"荒野","条件":function(){return 0===n.停留天数.荒野},"文本":["“你不配做一个父亲！”","“既然那么恨我！为什么要生下我！”","“没有你我照样可以活！”"]},{"区域":"荒野","条件":function(){return 1===n.停留天数.荒野},"文本":["晚上下起了雨，","又湿又冷，","帐篷底下渗进水来，","我蜷在睡袋里发抖。","但是，我是不会回去的！:-)"]},{"区域":"荒野","条件":function(){return 2===n.停留天数.荒野},"文本":["敏感、内向、偏执，","不愿在社交上投入任何时间，","几乎没什么朋友；","而我唯一的亲人，","现在也断了联系..."]},{"区域":"荒野","条件":function(){return 4===n.停留天数.荒野},"文本":["16年前，1988年的一个炎热的下午，","我出生在一个小山村。","母亲在我一岁时离家出走。","我的童年，","只有父亲醉酒后的叫骂声和远处的大山。"]},{"区域":"荒野","条件":function(){return 5===n.停留天数.荒野},"文本":["站在盘山的路上往下看，","县城的轮廓低低地趴在山脚下，","几间屋顶冒着炊烟。","我以后该怎么办?","到了县城再去想吧..."]},{"区域":"县城","条件":function(){return 1===n.停留天数.县城},"文本":["走了好几天，终于进了县城。","算不上城市，","顶多是个放大的乡镇，","几条街横着竖着，零散开着几家小店，","街上到处是从各个山村出来讨生活的人。"]},{"区域":"县城","条件":function(){return 6===n.停留天数.县城&&n.剧情.面试交钱},"文本函数":function(){return["按约定，我又去了昨天交钱的那个小区。","门开着，屋里没人，地上只剩一堆废纸。"]}},{"区域":"县城","条件":function(){return 12===n.停留天数.县城},"文本":["开始在固定的几个垃圾点“工作”。","早起，翻找，分类，卖掉。","一天能赚三四块，够买几个果子。","生活形成了一种可悲的规律。","我成了县城生态系统的一部分，","一个不起眼的清道夫。"]},{"区域":"县城","条件":function(){return 20===n.停留天数.县城},"文本":["未成年，没技能，不善言谈...","如果我死了，","会有人伤心吗？"]},{"区域":"县城","条件":function(){return 21===n.停留天数.县城},"文本":["街上围了一圈人看热闹，我也凑了过去。","人群中间是我父亲。","几个人死死拉着他的胳膊，他脸涨得通红，冲着路过的年轻人骂。","脾气一点没改，只是两鬓白了一大片。","我没敢多看，低着头快步走开。","明天一早就走，这县城待不下去了。"]},{"区域":"县城","条件":function(){return 22===n.停留天数.县城},"文本":["把县城那条老街从头走到尾。","早点铺冒着白汽，修车摊一股机油味，","放学的小孩在街上追着打闹。","这一切都与我无关。"]},{"区域":"山脉","条件":function(){return 0===n.停留天数.山脉},"文本":["深山之中寂静得可怕，连虫鸣都稀稀拉拉，","夜里林间的湿度极高，篝火无法驱散潮气。","可我偏偏贪恋这份无边的安静，","只有这里，才是完全属于我、不用设防的天地。"]},{"区域":"山脉","条件":function(){return 1===n.停留天数.山脉},"文本":["母亲抛下这个家出走的第二年，","父亲开始频繁带陌生女人回到家，","而我缩在角落，如同一件无关紧要的杂物，彻底被无视。","或者直白一点说，","在他眼里，我只是一个甩不掉的累赘......"]},{"区域":"山脉","条件":function(){return 2===n.停留天数.山脉},"文本":["他既不愿下地耕田劳作，也不会说软话哄身边的女人，","没过多久，那些女人全都相继离开了他。","自那以后，他性情愈发暴戾易怒，稍有不顺心就砸毁屋内为数不多的物件。"]},{"区域":"山脉","条件":function(){return 3===n.停留天数.山脉},"文本":["常年酗酒、作息混乱、饮食毫无节制，","父亲早早患上严重痛风，","深夜时常听见他疼得在床上翻滚，发出撕心裂肺的叫骂。","可即便受尽病痛折磨，第二天他依旧会买酒，喝到酩酊烂醉。"]},{"区域":"山脉","条件":function(){return 17===n.停留天数.山脉},"文本":["邻村曾有个我偷偷暗恋了许多年的女孩","她一双眼眸清澈纯粹，懵懂干净，像清晨薄雾笼罩、缓缓流淌的山中小河。","然而，","今年春节，在她辍学外出打工一年后，","我亲耳听到她对她妈吼道","“这种破地方！我TM再也不会回来了！......”"]},{"区域":"山脉","条件":function(){return 26===n.停留天数.山脉},"文本":["清冷月光穿过层层枝叶缝隙，斜斜落进简陋帐篷，","斑驳晃动的树影，伴着此起彼伏的夏虫低鸣轻轻摇曳。","我，","真的可以脱开一切关系，而独自存活吗？"]},{"区域":"山脉","条件":function(){return 27===n.停留天数.山脉},"文本":["世界上有这么一类人，","即使明知某种关系不健康，","却依然难以舍弃。","这是亲情、爱情、无奈、还是无知呢？"]},{"区域":"省城","条件":function(){return 0===n.停留天数.省城},"文本":["楼又高又密，巷子绕得像迷宫，我站在里头，不知道往哪边走。","我把帐篷搭在城中村外面一座大桥的桥洞底下，","里面早就住了人：一个不爱说话的中年大叔、一对老夫妻，还有一个胖胖的中年女人。"]},{"区域":"省城","条件":function(){return 3===n.停留天数.省城},"文本":["那对老人和胖女人看样子是一家人。","老太太一早出门，老头下午和夜里出去，总留一个守着那女人，寸步不离。","女人整天不是缩在被子里睡，就是盯着墙发呆，一声不吭......"]},{"区域":"省城","条件":function(){return 7===n.停留天数.省城},"文本":["深夜，老头和胖女人吵了起来。","“你努力一把、出去工作一下会怎样？”","“我这样的人谁肯要！”，这是我第一次听见那个女人说话。","“我死了以后、看你怎么办！”，老头大吼。","“不知道！”，女人顶了回去..."]},{"区域":"省城","条件":function(){return 8===n.停留天数.省城},"文本":["中年大叔一到晚上就咳得厉害。","可只要有钱，卖力气的钱也好，别人可怜他的钱也好，他都拿去买酒、买肉、买彩票。","呵呵。跟某人，像极了"]},{"区域":"省城","条件":function(){return 9===n.停留天数.省城},"文本":["那个叫碧瑶的吉他女孩，每天早出晚归，","夜里有一点动静，她就会猛地惊醒，坐起来四处看。"]},{"区域":"省城","条件":function(){return 17===n.停留天数.省城},"文本":["桥洞又搬来两个年轻人，大叔一开始挺高兴，觉得总算有人陪他说话。后来发现那两个都不爱搭理人，他就整天蹲在一边逗流浪猫。","他翻来覆去念叨的永远是那几件事：“只上过三年小学，除了自己名字，其余大字一个不识”，“要是哪天彩票中五百万，我就拿钞票铺一张大床躺着”。"]},{"区域":"省城","条件":function(){return 18===n.停留天数.省城},"文本":["“你身体这么差，怎么不去医院查查？”","“不能去。一查全是病，不查反倒能多活几年”，大叔说得很认真。"]},{"区域":"省城","条件":function(){return 21===n.停留天数.省城},"文本":["胖女人几天不吃、不喝，也不洗。","“你到底有啥苦嘛，我啥子也不要你做，不要求你成家，只希望你能自立，你为什么要把自己搞成这样？”","老头子一边说，一边抹眼泪。"]},{"区域":"省城","条件":function(){return 22===n.停留天数.省城},"文本":["“你知不知道那个女人和老人是啥关系？”","“那女的是老头的独生女儿，中学就得了‘郁闷症’，到现在一直靠老两口养着”，大叔一下来了精神，","“老头知道自己活不长，想最后拼一把，带女儿进城看病。为了省钱，就在桥洞下搭了个窝，一个星期去一次医院。”大叔接着说，","“不过我觉得她没啥病。说白点，就是懒...”"]},{"区域":"省城","条件":function(){return 24===n.停留天数.省城},"文本":["有一年冬天，我藏在箱底、准备买书的钱不见了。","我冲进屋里，看见地上的酒瓶和昏昏沉沉的父亲，一下就明白了。","我使劲踹了他一脚，扔下一句：“你这种懒人，就不该活着！”","然后我跑进山里躲了三天..."]},{"区域":"省城","条件":function(){return 25===n.停留天数.省城},"文本":["懒惰、愚蠢、随性，是我很早就给父亲贴上的三个标签。","这三个标签后来一次又一次被证实，一次又一次把我惹火，最后就钉死在那儿了。我开始不跟他说话，父子俩越走越远。","那我自己的标签是什么？冷漠？自私？孤僻？强势？我并不知道..."]},{"区域":"省城","条件":function(){return 27===n.停留天数.省城},"文本":["大叔晚上肚子疼得厉害，睡不着，把我拉起来聊天，","“哎，咱们要是病了只能硬抗呀！去年桥下有个糖尿病的老大爷，捡破烂的时候划伤了脚，没管，后来那口子一直烂到大腿，送到医院没几天就死了，遗体到现在都没人来领呢。”","我一句话也说不出来..."]},{"区域":"省城","条件":function(){return 32===n.停留天数.省城},"文本":["城中村巷道狭窄拥挤：地面潮湿肮脏，墙面小广告层层叠叠，墙缝间不时滴落浑浊污水，头顶仅留一线的窄窄天空缠绕着杂乱电线","这片方寸之地容纳了无数普通人：刚毕业四处碰壁的打工少年、怀揣明星梦漂泊异乡的年轻女孩、沿街摆摊糊口的小贩、无人赏识落魄潦倒的油画家、天真吵闹的孩童、一辈子孤身无依的独居老人。","这里，是一座永不落幕的人间百态戏台。"]},{"区域":"省城","条件":function(){return 35===n.停留天数.省城},"文本":["吃完从路边捡来的剩饭没多久，大叔突然捂着胸口干呕，趴在地上吐，最后吐出血来。","我跑到街上找巡逻民警。","民警来了，把他送去了附近的公立医院。"]},{"区域":"省城","条件":function(){return 37===n.停留天数.省城},"文本":["过了几天，大叔自己又回了桥洞。“检查结果怎么样？”，我赶紧问。","“胃里长了个瘤子，手术要八千块！”","我心里一沉。他倒很平静，慢慢说，","“光检查就花了医院不少钱，我心里过意不去，趁人不注意从病房溜出来了......”","“你可以去救助站住，那边比桥洞强多了！”","“不去。反正早晚都是一死，还不如自在点。至少这儿还有人跟我说说话。”","我一时语塞。"]},{"区域":"省城","条件":function(){return 42===n.停留天数.省城},"文本":["小时候，山里下过一场罕见的大雪。","屋檐下挂着一排冰棱。我站在门口跟伙伴吹牛，说自己练成了“轻功”。","他们都不信，笑我。我一急，拉着他们跑到结冰的水塘边。","才走两三步，脚下一滑，整个人掉进冰水里。还好路过的同乡叔叔把我捞了上来......","回家以后，父亲一边骂我「傻子」，一边往死里打。","我在床上躺了整整两个星期。"]},{"区域":"省城","条件":function(){return 43===n.停留天数.省城},"文本":["胖女人突然发了火，一脚把铁盆踢得咕噜噜响。","“你这病，就是闲出来的！你就是没吃过苦！”，老头子涨红了脸。","“那你让我死呀！！！”，胖女人冲他吼。","老太太头发散着，哭喊着抱住女儿的腿。","最后大叔拉住老头，碧瑶一直劝那个女人，这场风波才算压下去。"]},{"区域":"省城","条件":function(){return 44===n.停留天数.省城},"文本":["大叔疼得越来越勤，有时深夜我还能听见他咬牙咬得咯吱响。","“你不想回老家吗？”，我问他。","“晚啦！回不去啦！”","“就这么死在这儿，你甘心？”","“人都没了，还管这些干啥！你还年轻，这种事我一年要见好几回。”大叔看我的眼神有点疑惑。"]},{"区域":"省城","条件":function(){return 47===n.停留天数.省城},"文本":["村里逢年过节办祭山、放荷灯、舞彩船，父亲从来不去。他游手好闲，脾气又怪，村里人见了他都绕着走。","他也不在乎，照样喝酒闹事，甚至拎着菜刀去追往他家扔石头的小孩。在所有人眼里，他就是个说不通、也惹不起的怪人。"]},{"区域":"省城","条件":function(){return 50===n.停留天数.省城},"文本":["九月中旬，桥边的梧桐开始落叶，红了一片。桥洞底下一早一晚已经冷得刺骨。","一直哼哼着疼的大叔，抱着吉他的碧瑶，还有不知道往哪儿走的我。"]},{"区域":"省城","条件":function(){return 51===n.停留天数.省城},"文本":["大叔的肚子肿得越来越厉害，吃一点东西就胀得难受，常吐，浑身上下没一处不疼。","只能靠上次医院剩下的止痛药顶着，药劲上来才能眯一会儿。"]},{"区域":"省城","条件":function(){return 61===n.停留天数.省城},"文本":["中年大叔原本臃肿的身材，现在已经瘦成皮包骨。发霉的床单旁放着大伙给他买的水果、零食，但是他已经完全吃不下了。","我听见他在小声喊我，我赶忙过去，他蒙蒙脓脓的说道，","“你还很年轻...别把青春耗在这里...赶紧回去吧...好好充实自己...做个有用的人...不要像我一样...”","我流下了眼泪。"]},{"区域":"省城","条件":function(){return 62===n.停留天数.省城},"文本":["桥洞里的大叔，最后还是走了。","老头出门叫来巡逻民警，民警看了看现场，联系了民政局。","没多久，一辆白色的车停在桥边。大叔被装进一个黑色袋子里，不到一分钟，车就开走了，拐进车流，看不见了。我浑身猛地一颤，才反应过来，刚才那不是做梦。"]},{"区域":"省城","条件":function(){return 147===n.天数},"文本":["小时候山里穷，村里的小孩什么都敢吃：田边的青蛙、树上的蜂蛹、河滩的沙虫、山里的茅根、酸甜的覆盆子......","最好玩的还是晚上，叫上几个伙伴，揣一把弹弓、点个火把，钻进林子打鸟！","我家没人管，打到的野味都拎到我家去烤。","父亲在旁边馋得直咽口水，可谁也不给他分。有一回我们放下烤好的肉，跑去田里偷玉米，回来肉就没了，父亲说是野狗叼走的......"]},{"区域":"省城","条件":function(){return 148===n.天数},"文本":["胖女人忽然高兴起来，","一边洗碗一边哼歌，还过来跟我打招呼。看得我一头雾水。","难道她真是装的？"]},{"区域":"省城","条件":function(){return 150===n.天数},"文本":["碧瑶开始主动找胖女人说话，帮她梳头，两个人慢慢成了朋友。有空的时候，她还帮老两口洗衣服。","我忽然觉得自己有点问题。我惯了独来独往，谁也不靠，也从没想过怎么跟人处关系。"]},{"区域":"省城","条件":function(){return 153===n.天数},"文本":["可这份平静没撑多久，胖女人又开始整天睡，比之前还严重。","“你觉得她是装病博同情吗？”，我私下问碧瑶。","“不是装的。我有个特别好的朋友，跟她一模一样，一会儿低得不行，一会儿又特别兴奋。后来查出来是双相，重度抑郁加躁狂，常年吃药压着。”","“后来她好了吗？”","“不知道。她后来出国了，我们就没再联系过......”"]},{"区域":"省城","条件":function(){return 156===n.天数},"文本":["“你以后打算干什么？”，我问碧瑶。","“等阿姨好一点，我想回学校。我想当个会弹吉他的英语老师，嘻嘻~”","“你欠的那些钱呢？”，我又问。","“办法总会有的嘛~”，她眼睛里很亮。","“那你呢？你以后想干什么？总不能一辈子捡破烂吧”，碧瑶反过来问我。","我摇摇头，说不上来：“我不知道......”"]},{"区域":"省城","条件":function(){return 159===n.天数},"文本":["除了强大的野外求生能力，我好像什么都没有————工作技能、社交能力、身份和户口，还有最重要的、规划和理想。","我只是一个半成品，我需要为我的无知付出代价。"]},{"区域":"省城","条件":function(){return 165===n.天数},"文本":["一天比一天冷，秋风卷着落叶铺了一条街。","胖女人带着两个老人收拾东西，回遥远的老家去了。","老两口半辈子的积蓄全花在治病上，女儿一点没见好。","老头不担心自己老了没人管，他放不下的只有一件：他走了，女儿一个人怎么活。","至少现在，还看不到办法。"]},{"区域":"省城","条件":function(){return 167===n.天数},"文本":["走出阴冷潮湿的桥洞，缓步走到跨河石桥中央。","夜色彻底深沉，城市白日繁华尽数褪去，只剩空旷冷清的街道、光线昏暗的路灯，还有秋风卷动不停翻滚的枯黄落叶。","这座城市的夜空被高楼灯光遮蔽，不见半颗星辰。我不由想起老家山间那片质朴辽阔的夜幕，那里才是离天空最近的地方。"]},{"区域":"省城","条件":function(){return 169===n.天数},"文本":["整个十月都泡在雨里，淅淅沥沥没停过。","桥洞越来越冷清。","出不去捡东西，只能蹲在洞口逗流浪猫，熬着。","城里忽然变了样子，沿街挂满崭新的红装饰，","红底白字的横幅铺满街，处处写着——“热烈欢迎各位领导莅临XX市视察工作”。"]},{"区域":"省城","条件":function(){return 171===n.天数},"文本":["整座城突然绷了起来，扫地、冲水，街面刷得干干净净。","平常在街角、桥底、巷子里晃的流浪汉，全都不见了","街上干净得过分","没人讨论，没人追问，仿佛他们从未在这座城市存在过。"]},{"区域":"省城","条件":function(){return 173===n.天数},"文本":["1964年，一个叫吴晓雪的女孩，生在偏僻的山村。","她天生会唱会弹，吹拉弹唱样样拿得起来，是山里少见的有灵气的姑娘。","可命不偏爱谁。高考差了几分，她落榜了。","（待续）"]},{"区域":"省城","条件":function(){return 174===n.天数},"文本":["1980年，她不甘心一辈子困在山里，一个人去了县城，在小餐馆打工。","后厨有个不爱说话的年轻伙计，常帮她一把，让她心里有点暖，也有点感激。","没多久餐馆倒了，活路断了。","那年轻人说能给她找个更好的去处，把她骗回了与世隔绝的深山。","（待续）"]},{"区域":"省城","条件":function(){return 175===n.天数},"文本":["踏入深山牢笼，年轻人温柔的假象彻底撕碎，屡次强行禁锢、逼迫于她。","她无数次拼死出逃，每一次，都被对方父母连同全村人强行抓回。","等待她的，只有无休止的打骂与折辱，老两口日夜看守，封死她所有逃离的希望。","（待续）"]},{"区域":"省城","条件":function(){return 176===n.天数},"文本":["几年后，年轻人在外打工，工地上一根钢筋穿透右脚，截了肢，再也干不了活。","家里什么都没有了。","1983年，经人牵线，他们以一千六百块的价格，把她卖给了邻省大山里一个大她十岁的男人——杨世军。","（待续）"]},{"区域":"省城","条件":function(){return 177===n.天数},"文本":["杨世军懒散、游手好闲，人也不讲究，可唯独待她宽厚，没骂过她，也没动过手。","在黑暗和恶意里泡久了的人，一点点好就够她动容。","她慢慢松了防备，在这座贫瘠的大山里，暂且落了脚。","这点安稳很短，却是她半辈子少有的喘息。","（待续）"]},{"区域":"省城","条件":function(){return 178===n.天数},"文本":["为了报答这点好，她一个人把这个穷家撑了起来。","挑水、砍柴、种地、喂猪、编荆条，粗活重活全归她。","她天天劝，天天带，懒散的杨世军也慢慢肯下地干点活了。","破败的日子，总算有了一点起色。","（待续）"]},{"区域":"省城","条件":function(){return 179===n.天数},"文本":["1988年，她生下一个男孩","有了孩子，杨世军对她更上心，也更护着。","一年后，他第一次、也是唯一一次，放心让她一个人下山进城买东西。","走出那片困了她几年的山，她再没回头。","整整一个月没有音信，闭塞的村里才传来消息——","她一个人回了老家，从这座关了她半辈子的大山里跑了。","这个一辈子在自救的女人，是我的母亲，吴晓雪。","那个笨拙、粗俗、一辈子又穷又倔的男人，是我的父亲，杨世军。","他这辈子逢人最常念叨的一句，字字都硬：","“我不需要你们的可怜！”","（剧终）"],"选项":"梦该醒了"}]);u._RF.pop()}}}));

